import { catalogById } from "../../app/catalog";
import { fmtMm } from "../../lib/format";
import { useProject } from "../../state/projectStore";
import { useUi } from "../../state/uiStore";
import { useSceneModel } from "../../scene/useSceneModel";
import { Readout, Section } from "./fields";
import { Nameplate } from "./Nameplate";

/** A piece of hardware generated by an array (rail piece, clamp, L-foot, leg…). */
export function DerivedInspector({
  arrayId,
  partKey,
  catalogId,
}: {
  arrayId: string;
  partKey: string;
  catalogId: string;
}) {
  const scene = useSceneModel();
  const units = useProject((s) => s.project.settings.lengthUnits);
  const part = catalogById.get(catalogId);
  const L = scene.arrays.get(arrayId)?.layout;
  const rail = L?.rails.find((r) => r.key === partKey);
  const leg = L?.legs.find((l) => l.key === partKey);
  const rows: { label: string; value: string }[] = [];
  if (rail)
    rows.push(
      {
        label: "Piece length",
        value: `${fmtMm(rail.lengthMm, units)} (from ${rail.stockMm} mm stock)`,
      },
      { label: "Row / side", value: `${rail.row + 1} / ${rail.side}` },
    );
  if (leg)
    rows.push(
      { label: "Set length", value: fmtMm(leg.lengthMm, units) },
      { label: "Role", value: leg.role },
    );
  return (
    <div>
      <Section title="Array hardware">
        <p className="hint">
          Generated by the array tool. Change it in the{" "}
          <button
            type="button"
            className="link"
            onClick={() => useUi.getState().select({ kind: "array", id: arrayId })}
          >
            array settings
          </button>
          .
        </p>
        {rows.length > 0 && <Readout rows={rows} />}
      </Section>
      {part ? (
        <Nameplate part={part} />
      ) : (
        <p className="empty">Catalog part {catalogId} not found.</p>
      )}
    </div>
  );
}
